pub const ArkUI_NodeAttributeType_NODE_WATER_FLOW_ROW_GAP: ArkUI_NodeAttributeType = 1010004;
#[doc = " @brief Defines the water flow section configuration.\n This attribute can be set, reset, and obtained as required through APIs.\n\n **Format of the {@link ArkUI_AttributeItem} parameter for setting the attribute:**\n <ul>\n <li>.value[0].i32: An index calculated from 0 is converted to an integer, indicating that you want to start\n changing the position of the group.</li>\n <li>.object: {@link ArkUI_WaterFlowSectionOption} object.</li>\n </ul>\n\n **Format of the return value {@link ArkUI_AttributeItem}:**\n <ul>\n <li>.object: {@link ArkUI_WaterFlowSectionOption} object.</li>\n </ul>\n\n @ingroup Scrollable Container Component"]
pub const ArkUI_NodeAttributeType_NODE_WATER_FLOW_SECTION_OPTION: ArkUI_NodeAttributeType = 1010005;
